css:
.prima { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; color: #000; line-height: 1.35; }
.prima table { width: 100%; border-collapse: collapse; }
.prima td, .prima th { color: #000 !important; }
.prima .box { border: 1px solid #000; }
.prima .head td { padding: 2px 8px; vertical-align: top; }
.prima .title { text-align: center; font-weight: bold; text-decoration: underline; font-size: 13px; letter-spacing: 0.3px; padding-top: 4px !important; }
.prima .company { text-align: center; font-size: 16px; font-weight: bold; padding-top: 2px !important; }
.prima .muted { font-size: 9px; color: #333 !important; }
.prima .center { text-align: center; }
.prima .right { text-align: right; }
.prima .bold { font-weight: bold; }
.prima .nowrap { white-space: nowrap; }
.prima .party td { padding: 4px 8px; vertical-align: top; }
.prima .party .meta td { padding: 1.5px 4px; border: 0; }
.prima .party .name { font-weight: bold; font-size: 11px; }
.prima .items th { border: 1px solid #000 !important; padding: 5px 4px !important; font-weight: bold !important; color: #000 !important;
	background: #f2f2f2 !important; text-align: center; vertical-align: middle !important; font-size: 10.5px !important; line-height: 1.2; }
.prima .items th.num { text-align: right; }
.prima .items th.left { text-align: left; }
.prima .items td { border-left: 1px solid #000; border-right: 1px solid #000; padding: 4px; vertical-align: top; font-size: 10.5px; }
.prima .items tr.line td { border-bottom: 1px solid #000; }
.prima .num { text-align: right; white-space: nowrap; }
.prima .foot td { padding: 3px 8px; vertical-align: top; }
.prima .totals td { padding: 3px 8px; }
.prima .totals .grand td { border-top: 1px solid #000; font-weight: bold; font-size: 11.5px; }
.prima .sign-top { text-align: right; font-weight: bold; }
.prima .signs td { width: 33%; text-align: center; padding-top: 38px !important; }
.prima .items tr.total-row td { border-top: 1px solid #000; border-bottom: 1px solid #000; font-weight: bold; padding: 5px 4px; }
.prima .items tr.tax-row td { border-bottom: 1px solid #000; padding: 4px; }
.prima .items tr.grand-row td { border-bottom: 1px solid #000; font-weight: bold; font-size: 12px; padding: 6px 4px; background: #f2f2f2; }
.prima .items tr.total-row td[colspan], .prima .items tr.tax-row td[colspan], .prima .items tr.grand-row td[colspan] { border-right: 1px solid #000; }
